{
  "items": [
    {
      "need": "Comunicar imediatamente o incidente pelo canal de incidentes de Segurança da Informação.",
      "use": "direct",
      "condition": null,
      "scope_link": {
        "question_quote": "Enviei acidentalmente dados confidenciais a um fornecedor.",
        "explanation": "A regra exige comunicação imediata exatamente para o envio acidental de dados confidenciais a fornecedor; o procedimento identifica o canal."
      },
      "supports": [
        {
          "unit_id": "DOC-010::unit-a53055b0da14d0c1a709b3d0c6122c7b5e1f3dd9cd2db9b298381c1721583032",
          "quote": "If confidential data was accidentally sent to a supplier or carrier, the employee must report the incident immediately."
        },
        {
          "unit_id": "DOC-010::unit-a9c7e517c3f31638ca41139f6bb556a08ab55643595b47fedf8eebd5a0869fef",
          "quote": "Notify the Information Security incident channel immediately."
        }
      ]
    },
    {
      "need": "Interromper novas divulgações quando viável, sem destruir evidências.",
      "use": "direct",
      "condition": "Quando for viável interromper novas divulgações sem destruir evidências.",
      "scope_link": {
        "question_quote": "O que devo fazer agora?",
        "explanation": "É uma medida imediata de contenção do envio acidental relatado."
      },
      "supports": [
        {
          "unit_id": "DOC-010::unit-a9c7e517c3f31638ca41139f6bb556a08ab55643595b47fedf8eebd5a0869fef",
          "quote": "Stop further disclosure where feasible without destroying evidence."
        }
      ]
    },
    {
      "need": "Registrar as informações envolvidas, o destinatário, o meio de transmissão, o horário e a extensão conhecida do incidente.",
      "use": "direct",
      "condition": null,
      "scope_link": {
        "question_quote": "O que devo fazer agora?",
        "explanation": "O registro desses fatos integra a resposta imediata ao incidente, sem pressupor detalhes ainda desconhecidos."
      },
      "supports": [
        {
          "unit_id": "DOC-010::unit-a9c7e517c3f31638ca41139f6bb556a08ab55643595b47fedf8eebd5a0869fef",
          "quote": "Record what information was involved, recipient, transmission method, time, and known scope."
        }
      ]
    },
    {
      "need": "Não instruir o fornecedor a excluir evidências antes de receber orientação de Segurança da Informação.",
      "use": "direct",
      "condition": "Antes de Segurança da Informação fornecer orientação.",
      "scope_link": {
        "question_quote": "Enviei acidentalmente dados confidenciais a um fornecedor.",
        "explanation": "O fornecedor é o destinatário externo do incidente; a regra limita instruções de exclusão durante a resposta."
      },
      "supports": [
        {
          "unit_id": "DOC-010::unit-a9c7e517c3f31638ca41139f6bb556a08ab55643595b47fedf8eebd5a0869fef",
          "quote": "Do not instruct the external recipient to delete evidence before Information Security provides direction."
        }
      ]
    },
    {
      "need": "Preservar mensagens, registros, arquivos e capturas de tela relevantes.",
      "use": "direct",
      "condition": null,
      "scope_link": {
        "question_quote": "O que devo fazer agora?",
        "explanation": "A preservação das evidências é uma ação imediata prevista para tratar o incidente relatado."
      },
      "supports": [
        {
          "unit_id": "DOC-010::unit-a9c7e517c3f31638ca41139f6bb556a08ab55643595b47fedf8eebd5a0869fef",
          "quote": "Preserve relevant messages, logs, files, and screenshots."
        }
      ]
    },
    {
      "need": "Seguir as instruções de contenção, notificação e remediação emitidas pelo responsável pelo incidente.",
      "use": "direct",
      "condition": "Conforme forem emitidas instruções pelo responsável pelo incidente.",
      "scope_link": {
        "question_quote": "O que devo fazer agora?",
        "explanation": "A regra define como executar as próximas medidas de resposta sem inventar providências específicas."
      },
      "supports": [
        {
          "unit_id": "DOC-010::unit-a9c7e517c3f31638ca41139f6bb556a08ab55643595b47fedf8eebd5a0869fef",
          "quote": "Follow containment, notification, and remediation instructions issued by the incident owner."
        }
      ]
    },
    {
      "need": "Preservar o papel de Segurança da Informação na coordenação da contenção e na determinação de ações adicionais de Compras, Jurídico, Privacidade, responsável pelo negócio ou fornecedor.",
      "use": "direct",
      "condition": null,
      "scope_link": {
        "question_quote": "Enviei acidentalmente dados confidenciais a um fornecedor.",
        "explanation": "A regra específica para esse envio atribui a Segurança da Informação a coordenação e a decisão sobre ações adicionais, sem exigir o acionamento universal de todas as áreas."
      },
      "supports": [
        {
          "unit_id": "DOC-010::unit-a53055b0da14d0c1a709b3d0c6122c7b5e1f3dd9cd2db9b298381c1721583032",
          "quote": "Information Security coordinates containment and determines whether Procurement, Legal, Privacy, the business owner, or the supplier must take additional action."
        }
      ]
    },
    {
      "need": "Se a divulgação for material, não tentar ocultá-la nem resolvê-la de forma independente sem comunicá-la.",
      "use": "direct",
      "condition": "Se a divulgação for material.",
      "scope_link": {
        "question_quote": "O que devo fazer agora?",
        "explanation": "A regra limita a resposta individual a uma divulgação material; a condição é preservada sem afirmar que o incidente já foi classificado assim."
      },
      "supports": [
        {
          "unit_id": "DOC-006::unit-b7a3f71a2bf5bb9ed8e3fb4edd6ebd68fd859b27d673150b754d9b5c72ab7b07",
          "quote": "Employees must not attempt to conceal or independently resolve a material disclosure without reporting it."
        }
      ]
    }
  ],
  "action": {
    "kind": "complete"
  }
}

